<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientJwksJsonAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientJwksJsonAccessor trait.
 *
 * Covers null default, string/VO assignment via withJwksJson,
 * getJwksJson/jwksJson accessors, and isJwksJsonChanged with/without original.
 */
class TrustedClientJwksJsonAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withJwksJson creates a new instance with the JwksJson set
     * from a string value, and getJwksJson returns the primitive string.
     */
    public function testWithJwksJsonFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientJwksJsonAccessorUnitTest();

        // Act
        $result = $holder->withJwksJson('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getJwksJson());
    }
    /**
     * Asserts that withjwksJson has access to the value object
     * from a string value, and getJwksJson returns the primitive string.
     */
    public function testWithJwksJsonFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientJwksJsonAccessorUnitTest();

        // Act
        $result = $holder->withJwksJson('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->jwksJson()->value());
    }
    public function testChangedJwksJson(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientJwksJsonAccessorUnitTest();
        $original = $holder->withJwksJson('one');
        $same = $holder->withJwksJson('one');
        $modified = $holder->withJwksJson('other');

        // Act
        $unchanged = $holder->isJwksJsonChanged();
        $withSame = $original->isJwksJsonChanged($same);
        $withDiferent = $original->isJwksJsonChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientJwksJsonAccessorUnitTest
{
    use TrustedClientJwksJsonAccessor;
}
